package com.chubb.apac.claims.modulith.inforequest.repository;
import com.chubb.apac.claims.modulith.inforequest.model.*;import java.time.LocalDate;import java.util.List;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest class InformationRequestRepositoryTest {@Autowired InformationRequestRepository repository;@Test void findsByClaim(){InformationRequest r=new InformationRequest();r.setRequestId("IRQ-1");r.setClaimId("CLM-1");r.setRequestedFields(List.of("Invoice"));r.setDueDate(LocalDate.now());r.setStatus(InformationRequestStatus.PENDING);r.setRequestedBy("S1");r.setCreatedBy("S1");r.setUpdatedBy("S1");repository.saveAndFlush(r);assertThat(repository.findByClaimIdOrderByCreatedAtDesc("CLM-1")).hasSize(1);}}
